from .monitoring import EnergyEfficiencyMonitoring


class energy_efficiency_monitoring(object):
    ROBOT_LIBRARY_SCOPE = "TEST SUITE"

    def __init__(self):
        super().__init__()
        self.ee_monitoring_obj = EnergyEfficiencyMonitoring()

    def configure_bts_connection(self, ip_address='192.168.255.129', username='Nemuadmin', password='nemuuser', **kwargs):
        """
        Configure parameters for BTS connection.
        :param ip_address: IP of BTS; default 192.168.255.129
        :type  ip_address: str
        :param username:   name of BTS user; default Nemuadmin
        :type  username:   str
        :param password:   password to log in for BTS user; default nemuuser
        :type  password:   str
        :param kwargs:     other named parameters supported by connect_to method from taf.sbts.oam.coam.admin library
        :return: None
        """
        self.ee_monitoring_obj.configure_admin_connection(ip_address=ip_address, username=username, password=password,
                                                          **kwargs)

    def enable_energy_efficiency_monitoring(self, **target_monitoring_params_values):
        """
        Set required parameters in BTS configuration to enable energy efficiency monitoring counters collection.
        Skip recommissioning if parameters are already set correctly.
        :param target_monitoring_params_values: named parameters in format param_name=param_value.
        Attention! Parameters have default values used when you don't give any values here:
            actPowerMeter='true',
            mtBtsEnergyMonitoring='15min',
            mtSBTSRfmEnergyMonitoring='15min',
            mtSBTSSmEnergyMonitoring='15min'
        You can overwrite one or more values or leave default ones.
        :return: None
        """
        if target_monitoring_params_values:
            self.ee_monitoring_obj.modify_default_monitoring_params_values(**target_monitoring_params_values)
        if not self.ee_monitoring_obj.verify_all_monitoring_params_are_set_correctly():
            self.ee_monitoring_obj.recommission_monitoring_params_with_target_values()

    def disable_energy_efficiency_monitoring(self):
        """
        Set required parameters in BTS configuration to disable energy efficiency monitoring counters collection.
        :return: None
        """
        self.ee_monitoring_obj.recommission_monitoring_params_with_disabled_values()

    def get_counters_difference_for_enabled_disabled_features(self):
        """
        Count the difference between counters' values collected when EE feature was disabled and
        when EE feature was enabled. If more than one interval passed during measurement period the values are summed up
        keeping the same number of records for disabled and enabled measurement period.
        :return: dict in format:
        {
            'M40002C0': {
                'diff': {'kWh': -0.00046, 'raw': -46.0},
                'disabled': {'kWh': 0.08535, 'raw': 8535.0},
                'enabled': {'kWh': 0.08581, 'raw': 8581.0},
                'interval': '15min',
                'percentage gain': '-0.54%'
            },
            'M40002C1': {
                'diff': {'kWh': -0.0003, 'raw': -30.0},
                'disabled': {'kWh': 0.25901, 'raw': 25901.0},
                'enabled': {'kWh': 0.25931, 'raw': 25931.0},
                'interval': '15min',
                'percentage gain': '-0.12%'
            },
            'M40002C2': {
                'diff': {'kWh': -0.00076, 'raw': -76.0},
                'disabled': {'kWh': 0.34436, 'raw': 34436.0},
                'enabled': {'kWh': 0.34512, 'raw': 34512.0},
                'interval': '15min',
                'percentage gain': '-0.22%'
            }
        }
        """
        return self.ee_monitoring_obj.get_counters_difference_for_enabled_disabled_features()

    def get_energy_consumption_counters_values(self):
        """
        Get values of all BTS energy consumption counters
        :return: dict in format
        {
            'counter_name' : {
                'timestamp1' : value1,
                'timestamp2' : value2,
                ...
            }
        }
        """
        return self.ee_monitoring_obj.get_energy_consumption_counters_values()

    def save_energy_consumption_counters_values(self, ee_features_status='enabled', filepath=None):
        """
        Save current values of energy consumption counters for given EE features status.
        Additionally log them to JSON file.
        :param ee_features_status: disabled or enabled
        :type  ee_features_status: str
        :param filepath:           full path to JSON file where the counters are saved
        :type  filepath:           str
        :return: None
        """
        self.ee_monitoring_obj.save_energy_consumption_counters_values(
            ee_features_status=ee_features_status,
            filepath=filepath
        )

    def start_measurement_period(self, ee_features_status, interval='15min'):
        """
        Save start time of period during which are collected counters that will be included in counting difference
        in power consumption between enabled and disabled features.
        :param ee_features_status: disabled or enabled
        :type  ee_features_status: str
        :param interval:           time interval set for counters collection
        :type  interval:           str
        :return: None
        """
        self.ee_monitoring_obj.start_measurement_period(ee_features_status=ee_features_status, interval=interval)

    def stop_measurement_period(self, ee_features_status):
        """
        Save stop time of period during which are collected counters that will be included in counting difference
        in power consumption between enabled and disabled features.
        :param ee_features_status: disabled or enabled
        :type  ee_features_status: str
        :return: None
        """
        self.ee_monitoring_obj.stop_measurement_period(ee_features_status=ee_features_status)

    def wait_for_next_pm_period(self, interval='15min', delay=30):
        """
        Wait for the next counter cycle, indicated by the interval
        :param interval: Interval of the counter in minutes, e.g. "15min"
        :type  interval: str
        :param delay:    Number of seconds to wait after the new period starts
        :type  delay:    int
        :return: pm_period_start_time, pm_period_end_time
        """
        return self.ee_monitoring_obj.wait_for_next_pm_period(interval=interval, delay=delay)
